const on = b.frag_on ? 1 : 0, pk = cleanFragPackets(b.frag_packets, ''), ln = cleanFragRange(b.frag_length, ''), iv = cleanFragRange(b.frag_interval, '');
if (on && (!pk || !ln || !iv)) return J({ ok: false, error: 'مقدار Fragment نامعتبر است (مثلاً tlshello ، 100-200 ، 10-20)' }, 400);
