if (bk.format !== 'vex-panel-backup' || !Array.isArray(bk.users) || !bk.settings || typeof bk.settings !== 'object') return J({ ok: false, error: 'فایل بکاپ معتبر نیست' }, 400);
if (bk.users.length > 5000) return J({ ok: false, error: 'تعداد کاربرها بیش از حد مجاز است' }, 400);
const SAFE = /^[a-z_]{1,40}$/;
const stmts = [env.DB.prepare('DELETE FROM users')];
for (const u of bk.users) {
if (!u || typeof u !== 'object' || !u.uuid || !u.token) return J({ ok: false, error: 'اطلاعات یکی از کاربرها ناقص است' }, 400);
const cols = Object.keys(u).filter((c) => SAFE.test(c));
stmts.push(env.DB.prepare('INSERT INTO users(' + cols.join(',') + ') VALUES(' + cols.map(() => '?').join(',') + ')').bind(...cols.map((c) => (u[c] === undefined ? null : u[c]))));
}
