const TG_NAME = /^[a-zA-Z0-9_-]{1,40}$/;
const faNum = (t) => String(t || '').replace(/[\u06F0-\u06F9]/g, (c) => String(c.charCodeAt(0) - 1776)).replace(/[\u0660-\u0669]/g, (c) => String(c.charCodeAt(0) - 1632)).trim();
const tgStyle = (d) => /^a:(del|delok|regen|regenok)/.test(d) ? 'danger' : /^(c:new)/.test(d) ? 'success' : /^(m|c:list|c:stats|c:find|c:expiring|c:help)/.test(d) ? 'primary' : undefined;
const tgKb = (rows) => ({ inline_keyboard: rows.map((r) => r.map(([text, data]) => ({ text, callback_data: data, style: tgStyle(data) }))) });
const TG_BANNER_B64 = '';
let TG_FID = null;
async function tgPhoto(token, chat, caption, rows) {
  const cap = String(caption || '').slice(0, 1000);
  if (TG_FID) { const r = await tgApi(token, 'sendPhoto', { chat_id: chat, photo: TG_FID, caption: cap, reply_markup: rows ? tgKb(rows) : undefined }); if (r.ok) return r; TG_FID = null; }
  try {
    const fd = new FormData(); fd.append('chat_id', String(chat)); fd.append('caption', cap);
    if (rows) fd.append('reply_markup', JSON.stringify(tgKb(rows)));
    fd.append('photo', new Blob([Uint8Array.from(atob(TG_BANNER_B64), (c) => c.charCodeAt(0))], { type: 'image/jpeg' }), 'vex.jpg');
    const j = await (await fetch('https://api.telegram.org/bot' + token + '/sendPhoto', { method: 'POST', body: fd })).json();
    if (j.ok && j.result && j.result.photo) TG_FID = j.result.photo[j.result.photo.length - 1].file_id;
    return j;
  } catch (e) { return { ok: false }; }
}
const tgMain = [[['ساخت سرویس', 'c:new'], ['لیست سرویس‌ها', 'c:list:0']], [['جستجو', 'c:find'], ['رو به اتمام', 'c:expiring']], [['آمار', 'c:stats'], ['روشن/خاموش کل', 'c:gtog']], [['راهنما', 'c:help']]];
const TG_HELP = 'راهنمای پنل Vex\n\nساخت سرویس: با پروفایل آماده یا حالت دلخواه.\nلیست و جستجو: مدیریت هر سرویس با دکمه‌ها.\nرو به اتمام: سرویس‌هایی که کمتر از ۳ روز یا ۱۰٪ حجم دارند.\nآمار: تعداد سرویس‌ها، آنلاین‌ها و ترافیک امروز.\nروشن/خاموش کل: قطع یا وصل همه سرویس‌ها.';
async function tgApi(token, method, body) { try { const r = await fetch('https://api.telegram.org/bot' + token + '/' + method, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }); return await r.json(); } catch (e) { return { ok: false }; } }
const tgSend = (token, chat, text, rows) => (rows === tgMain ? tgPhoto(token, chat, text, rows) : tgApi(token, 'sendMessage', { chat_id: chat, text: text, reply_markup: rows ? tgKb(rows) : undefined }));
