const tgSetState = (env, s) => setSet(env, 'tg_state', s ? JSON.stringify(s) : '');
async function tgCall(env, url, act, body) {
  const t = hex(24);
  await env.DB.prepare('INSERT INTO sessions(t,exp) VALUES(?,?)').bind(t, now() + 60).run();
  try {
    const req = new Request(url.origin + '/tg', { method: 'POST', headers: { 'X-Req': '1', 'X-Panel-Session': t, 'Content-Type': 'application/json', 'CF-Connecting-IP': 'telegram' }, body: JSON.stringify(body || {}) });
    return await (await panelApi(req, env, act, url)).json();
  } catch (e) { return { ok: false, error: 'خطا در انجام عملیات' }; }
  finally { await env.DB.prepare('DELETE FROM sessions WHERE t=?').bind(t).run(); }
}
